CREATE POLICY "own materiais select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'materiais' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "own materiais insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'materiais' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "own materiais update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'materiais' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "own materiais delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'materiais' AND auth.uid()::text = (storage.foldername(name))[1]);